import { answerQuestion, questions, quizzes, names } from './guide-knowledge.js';
const $=id=>document.getElementById(id),panel=$('space-guide'),log=$('guide-messages'),suggestions=$('guide-suggestions');let previousFocus,lastRandom=-1,lastQuiz=-1;
function message(text,role='bot',source){const row=document.createElement('div');row.className='guide-message '+role;const label=document.createElement('small');label.textContent=role==='bot'?'ORBIT GUIDE':'YOU';const body=document.createElement('p');body.textContent=text;row.append(label,body);if(source){const a=document.createElement('a');a.href=source;a.target='_blank';a.rel='noopener';a.textContent='Read more · NASA ↗';row.append(a)}log.append(row);while(log.children.length>70)log.firstElementChild.remove();log.scrollTop=log.scrollHeight;return row}
function suggest(topic){suggestions.replaceChildren();const pool=topic===undefined?[questions[10],questions[27],questions[34]]:questions.filter(q=>q.topic===topic);pool.forEach(q=>{const b=document.createElement('button');b.type='button';b.textContent=q.question;b.onclick=()=>ask(q.question);suggestions.append(b)})}
function ask(text){const value=text.trim().slice(0,500);if(!value)return;message(value,'user');const a=answerQuestion(value);message((a.related?'Here’s a related fact from the atlas: ':'')+a.answer,'bot',a.source);suggest(a.topic);$('guide-input').value=''}
function randomIndex(length,last){if(last<0)return Math.floor(Math.random()*length);let i=Math.floor(Math.random()*(length-1));if(i>=last&&last>=0)i++;return i}
function open(){previousFocus=document.activeElement;panel.hidden=false;$('guide-toggle').setAttribute('aria-expanded','true');$('guide-input').focus();log.scrollTop=log.scrollHeight}
function close(){panel.hidden=true;$('guide-toggle').setAttribute('aria-expanded','false');(previousFocus||$('guide-toggle')).focus()}
$('guide-toggle').onclick=()=>panel.hidden?open():close();$('guide-close').onclick=close;panel.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();close()}});$('guide-form').addEventListener('submit',e=>{e.preventDefault();ask($('guide-input').value)});
$('guide-random').onclick=()=>{lastRandom=randomIndex(questions.length,lastRandom);ask(questions[lastRandom].question)};
$('guide-quiz').onclick=()=>{lastQuiz=randomIndex(quizzes.length,lastQuiz);const quiz=quizzes[lastQuiz];const row=message(quiz.q),answers=document.createElement('div');answers.className='quiz-answers';quiz.choices.forEach((choice,index)=>{const b=document.createElement('button');b.type='button';b.textContent=choice;b.onclick=()=>{answers.querySelectorAll('button').forEach(button=>button.disabled=true);b.classList.add(index===quiz.correct?'correct':'incorrect');answers.children[quiz.correct].classList.add('correct');message(choice,'user');const fact=questions[quiz.fact];message((index===quiz.correct?'Correct! ':'The answer is '+quiz.choices[quiz.correct]+'. ')+fact.answer,'bot',fact.source);suggest(fact.topic)};answers.append(b)});row.append(answers);log.scrollTop=log.scrollHeight};
$('guide-clear').onclick=()=>{log.replaceChildren();welcome()};
function welcome(){message('Hello, explorer! I’m your space guide. Ask about our cosmic neighborhood, discover a random question, or try a quick quiz. My answers come from this atlas’s curated facts.');suggest()};welcome();
